        return ADCS_E_NULL;
    }

    if (!adcs_is_finite_vec3(first) || !adcs_is_finite_vec3(second)) {
        *separation_rad = 0.0;
        *conditioning = 0.0;
        return ADCS_E_NOT_FINITE;
    }

    adcs_vec3_t u, v;
    if (adcs_vec3_normalize(first, ADCS_EPS_NORM, &u) != ADCS_OK) {
        *separation_rad = 0.0;
        *conditioning = 0.0;
        return ADCS_E_DEGENERATE;
    }
    if (adcs_vec3_normalize(second, ADCS_EPS_NORM, &v) != ADCS_OK) {
        *separation_rad = 0.0;
        *conditioning = 0.0;
        return ADCS_E_DEGENERATE;
    }

    double dot = adcs_vec3_dot(&u, &v);
    dot = ADCS_CLAMP(dot, -1.0, 1.0);
    *separation_rad = acos(dot);

    adcs_vec3_t cross = adcs_vec3_cross(&u, &v);
    *conditioning = adcs_vec3_norm(&cross);

    return ADCS_OK;
}

